```
library(shiny)

ui <- basicPage(
  shinyFiles::shinyDirButton(
    id = "test_dir_select",
    label = "Choose directory",
    title = "Directory selection",
    icon = shiny::icon("folder")
  ),
  shiny::htmlOutput("test_dir_select_ready")
)

server <- function(input, output) {
  
  osSystem <- Sys.info()["sysname"]
  if (osSystem == "Linux") {
    def_roots <- c(home = "~")
  } else {
    def_roots <- shinyFiles::getVolumes()
  }
  
  shinyFiles::shinyDirChoose(input, 'test_dir_select', roots = def_roots)  
  
  test_dir_select_ready <- shiny::reactive({
    if(length(input$test_dir_select) == 1) {
      path <- "not yet definded"
    } else {
      if (osSystem == "Linux") {
        path <- file.path(
          def_roots,
          paste(unlist(input$test_dir_select$path[-1]), collapse = .Platform$file.sep),
          "new_folder"
        )
      } else {
        path <- file.path(
          paste(unlist(input$test_dir_select$path), collapse = .Platform$file.sep),
          "new_folder"
        )
      }
    }
    return(path)
  })
  
  output$test_dir_select_ready <- shiny::renderUI({
    shiny::HTML("<font color=\"red\">", test_dir_select_ready(), "</font>")
  })
  
}

shinyApp(ui, server)
